package com.ligamunicipal.api;
import com.ligamunicipal.api.service.InitialDataService; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean; import org.springframework.boot.CommandLineRunner; import org.springframework.web.servlet.config.annotation.CorsRegistry; import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
@SpringBootApplication public class LigaMunicipalApplication { public static void main(String[] args){SpringApplication.run(LigaMunicipalApplication.class,args);} @Bean WebMvcConfigurer cors(){return new WebMvcConfigurer(){public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOrigins("http://localhost:4200").allowedMethods("*").allowedHeaders("*");}};} @Bean CommandLineRunner seedData(InitialDataService initialData){return args->initialData.seed();} }
